using System.Text.Json;
using System.Text.Json.Serialization.Metadata;

var options = new JsonSerializerOptions(JsonSerializerDefaults.Web);

// 1) Strongly-typed metadata: GetTypeInfo<T>() returns JsonTypeInfo<T> directly.
JsonTypeInfo<int[]> arrayInfo = options.GetTypeInfo<int[]>();
Console.WriteLine($"Typed metadata for int[]: {arrayInfo.Type}");

int[] demo = JsonSerializer.Deserialize("""[1,2,3]""", arrayInfo)!;
Console.WriteLine($"Deserialized: [{string.Join(", ", demo)}]");

// 2) Probe without throwing: TryGetTypeInfo returns false when
//    metadata isn't available (e.g. a source-gen-only context).
bool found = options.TryGetTypeInfo(typeof(int[]), out JsonTypeInfo? info);
Console.WriteLine($"\nTryGetTypeInfo(int[])  => found={found}, type={info?.Type}");

// Demonstrate the "not found" path using a resolver that knows nothing.
var limited = new JsonSerializerOptions
{
    TypeInfoResolver = JsonTypeInfoResolver.Combine() // empty — resolves nothing
};
bool found2 = limited.TryGetTypeInfo(typeof(int[]), out JsonTypeInfo? info2);
Console.WriteLine($"TryGetTypeInfo(int[]) on empty resolver => found={found2}, info={info2?.Type?.ToString() ?? "(null)"}");

